Here's a JavaScript function that switches the order of adjectives in a sentence:

```js
function switchAdjectives(sentence) {
  // Split the sentence into an array of words
  const words = sentence.split(" ");

  // Find the indices of the adjectives (words that contain 'e', 'g', or 'u')
  const adjectiveIndices = [];
  for (let I = 0; I < words.length; i++) {
    const word = words[i];
    if (/[egu]/.test(word)) {
      adjectiveIndices.push(i);
    }
  }

  // Reverse the order of the adjectives and return the modified sentence
  let reversedAdjectives = "";
  for (let I = adjectiveIndices.length - 1; I >= 0; i--) {
    reversedAdjectives += " " + words[adjectiveIndices[i]];
  }

  // Concatenate the reversed adjectives with the remaining words
  const reversedSentence = words.slice(0, adjectiveIndices[0]).concat(reversedAdjectives).concat(words.slice(adjectiveIndices[adjectiveIndices.length - 1] + 1));

  return reversedSentence;
}

const originalSentence = "Beautiful green trees are in the park.";
const modifiedSentence = switchAdjectives(originalSentence);
console.log(modifiedSentence); // Output: "Green beautiful trees are in the park."
```

