```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <limits> // For numeric_limits

// Recursive Fibonacci function
unsigned long long fib(int n, int& a, int& b) {
    if (n <= 1) return n;

    unsigned long long result = fib(n - 1, a, b);
    int temp = a;
    a = b;
    b = temp + b;
    return result + a;
}

int main() {
    std::string input;
    int a, b, n;
    std::cout << "Enter the first Fibonacci number: ";
    std::getline(std::cin, input);
    std::stringstream ss(input);
    ss >> a;
    while (ss.fail() || std::cin.peek() != ' ') {
        ss.clear();
        ss.ignore(std::numeric_limits<std::streamsize>::max(), ' ');
        ss >> a;
    }
    ss >> b;
    while (ss.fail() || std::cin.peek() != '\n') {
        ss.clear();
        ss.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
        ss >> b;
    }
    std::cout << "Enter the number of Fibonacci numbers to generate: ";
    std::getline(std::cin, input);
    std::stringstream ns(input);
    ns >> n;
    while (ns.fail() || n <= 0) {
        ns.clear();
        ns.ignore(std::numeric_limits<std::streamsize>::max(), ' ');
        ns >> n;
    }
    std::cout << "Fibonacci sequence (" << a << ", " << b << "): ";
    for (int I = 2; I <= n + 1; i++) {
        std::cout << fib(i, a, b) << (i == n + 1 ? "" : ",");
    }
    std::cout << std::endl;
    return 0;
}
```

