```csharp
using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;

namespace RestServiceWrapper
{
    public abstract class RestServiceBase
    {
        private string baseUrl;
        private string authToken;
        private HttpClient httpClient;

        protected RestServiceBase(string baseUrl, string authToken)
        {
            this.baseUrl = baseUrl;
            this.authToken = authToken;
            this.httpClient = new HttpClient();
        }

        protected async Task<T> GetAsync<T>(string uri)
        {
            var requestUri = CombineUrls(uri);
            using (var request = new HttpRequestMessage(HttpMethod.Get, requestUri))
            {
                AddAuthorizationHeader();
                var response = await httpClient.SendAsync(request);
                response.EnsureSuccessStatusCode();
                return await DeserializeResponseAsync<T>(response);
            }
        }

        protected async Task<TResult> PostAsync<T, TResult>(string uri, T body)
        {
            var requestUri = CombineUrls(uri);
            using (var content = new StringContent(SerializeObject(body), Encoding.UTF8, "application/json"))
            {
                using (var request = new HttpRequestMessage(HttpMethod.Post, requestUri))
                {
                    AddAuthorizationHeader();
                    request.Content = content;
                    var response = await httpClient.SendAsync(request);
                    response.EnsureSuccessStatusCode();
                    return await DeserializeResponseAsync<TResult>(response);
                }
            }
        }

        private void AddAuthorizationHeader()
        {
            httpClient.DefaultRequestHeaders.Add("Authorization", $"Bearer {authToken}");
        }

        private Uri CombineUrls(string relativeUrl)
        {
            var builder = new UriBuilder(baseUrl);
            builder.Path += relativeUrl.StartsWith("/") ? relativeUrl.

