Here's a Javascript function that takes a string variable in dot notation and returns all entries in an object where the nested key value matches the string key:

```javascript
function findEntriesByKey(obj, keyPath) {
  const keys = keyPath.split(".");
  let currentObj = obj;
  const results = [];

  keys.forEach((key) => {
    if (currentObj[key] !== undefined) {
      currentObj = currentObj[key];
    } else {
      return; // If any key is not found, stop searching and return empty array
    }
  });

  results.push(currentObj); // Add the final object to the results array

  // Traverse up the object hierarchy and add all objects with matching key values
  for (let I = keys.length - 2; I >= 0; i--) {
    const parentKey = keys[i];
    const parentObj = {};

    for (let j = I + 1; j < keys.length; j++) {
      const childKey = keys[j];
      const childValue = currentObj[childKey];

      // Create an object containing only the parent key and its corresponding value
      parentObj[parentKey] = childValue;

      // Check if there are other objects in the same level of the hierarchy with the same parent key
      const siblings = Object.keys(currentObj).filter((k) => k !== parentKey && currentObj[k][childKey] === childValue);

      // Merge the parent key and its corresponding value with the sibling objects
      siblings.forEach((siblingKey) => {
        parentObj[siblingKey] = currentObj[siblingKey];
      });

      // Push the merged object containing both the parent key and its corresponding value as well as all other objects with the same parent key and matching key value
      results.push(Object.assign({}, parentObj));
    }

    // Move back up one level in the object hierarchy
    currentObj = currentObj[parentKey];
  }

  return results;
}
```

